<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Sorting Visualizer</title>
<style>
    body {
        background-color: #1a1a1a;
        color: #e0e0e0;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        min-height: 100vh;
        margin: 0;
    }

    #bars {
        width: 90%;
        max-width: 800px;
        height: 400px;
        background-color: #2c2c2c;
        display: flex;
        justify-content: space-around;
        align-items: flex-end; /* Align bars to bottom */
        border-radius: 6px;
        padding: 10px;
        margin-bottom: 30px;
    }

    .bar {
        width: auto; 
        min-width: 15px;
        background-color: #4a90e2;
        margin: 0 4px; /* Gap between bars */
        border-radius: 2px 2px 0 0;
        transition: height 0.2s ease, background-color 0.15s ease;
    }

    #controls {
        display: flex;
        gap: 10px;
        margin-top: 20px;
    }

    button {
        padding: 10px 20px;
        font-size: 16px;
        cursor: pointer;
        background-color: #4a90e2;
        color: white;
        border: none;
        border-radius: 4px;
        transition: opacity 0.2s, transform 0.1s;
    }

    button:hover { opacity: 0.85; }
    button:active { transform: translateY(1px); }

</style>
</head>
<body>

<div id="bars"></div>

<div id="controls">
    <button id="sort">Sort Ascending</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
</div>

<script>
(function() {
    // Internal state for array and DOM bars
    let _currentArray = [];
    let _barsDOM = []; 
    const containerEl = document.getElementById('bars');

    // Bubble sort indices: i (outer pass index), j (inner loop current index)
    let _sortState = { i: 0, j: 0 };

    function renderBars() {
        if (_currentArray.length === 0) {
            containerEl.innerHTML = '';
            _barsDOM = [];
            return;
        }

        // If DOM elements count doesn't match array length (due to resizing), rebuild.
        if (_currentArray.length !== _barsDOM.length) {
            containerEl.innerHTML = '';
            _barsDOM = [];

            let maxVal = Math.max(..._currentArray, 1); 

            for (let val of _currentArray) {
                const b = document.createElement('div');
                b.className = 'bar';
                // Normalize height relative to container's available space.
                // Use a fixed percentage range: min-height 5% max-height ~90% of container height.
                const hPercent = Math.max(5, (val / maxVal) * 90); 

                b.style.height = hPercent + '%';
                containerEl.appendChild(b);
                _barsDOM.push(b);
            }
        } else {
            // Update heights based on current values for animation
            let maxVal = Math.max(..._currentArray, 1);
            for (let idx in _currentArray) {
                if (_barsDOM[idx]) {
                    const val = _currentArray[idx];
                    const hPercent = Math.max(5, (val / maxVal) * 90);
                    _barsDOM[idx].style.height = hPercent + '%';
                }
            }
        }
    }

    window.viz = {
        array: function() { return _currentArray; }, 
        setArray: function(a) {
            _currentArray = a.slice(); // Store copy
            renderBars();
            // Reset sort progress for new data
            _sortState = { i: 0, j: 0 };
        },

        sorted: function() {
            if (_currentArray.length < 2) return true;
            for (let k = 1; k < _currentArray.length; k++) {
                if (_currentArray[k] < _currentArray[k-1]) return false;
            }
            return true;
        },

        sortStep: function() {
            // If already sorted by value check, we can stop immediately.
            if (this.sorted()) {
                // Reset state to avoid getting stuck? Or just let it stay done.
                _sortState = { i: 0, j: 0 }; 
                return true;
            }

            const arr = _currentArray; 
            const len = arr.length;

            if (len < 2) return false; // Should not happen with sorted check above

            // Bubble Sort Logic State Machine

            // Check if we have exhausted outer loop passes.
            // Outer index i goes from 0 to len-2 inclusive for valid swaps.
            // If _sortState.i >= len - 1, it means the last pass (len-2) has been completed.
            if (_sortState.i >= len - 1) {
                return true; 
            }

            let i = _sortState.i || 0;
            let j = _sortState.j || 0;

            // Inner loop bound: j < len - 1 - i. Max valid index for comparison is (len-2-i).
            const maxInnerIndex = len - 2 - i; 

            if (j > maxInnerIndex) {
                // End of inner loop pass reached, move to next outer index.
                _sortState.i++;
                _sortState.j = 0; 
                return false; // No comparison performed this tick, but state advanced.
            }

            // Perform ONE Comparison and Swap (The Step)

            if (arr[j] > arr[j+1]) {
                [arr[j], arr[j+1]] = [arr[j+1], arr[j]];
                renderBars(); // Update DOM for swap visual
            }

            _sortState.j++; // Advance j for next call

            return false;
        },
    };

    function generateRandomArray(count) {
        count = count || 30;
        const minVal = 5, maxVal = 120;
        return Array.from({length: count}, () => Math.floor(Math.random() * (maxVal - minVal + 1)) + minVal);
    }

    // Initialize with some random data
    window.viz.setArray(generateRandomArray(30));


    document.getElementById('shuffle').addEventListener('click', function() {
        const newArr = generateRandomArray(30);
        window.viz.setArray(newArr);
    });

    document.getElementById('reset').addEventListener('click', function() {
        // Reset usually implies clearing current work and maybe going back to initial state. 
        // We'll just shuffle again for simplicity as "Reset" often means restart from random in these tasks.
        window.viz.setArray(generateRandomArray(30));
    });

    document.getElementById('sort').addEventListener('click', function() {
        if (window.viz.sorted()) return; // Already sorted

        const intervalId = setInterval(() => {
            window.viz.sortStep();

            if (window.viz.sorted()) clearInterval(intervalId);
        }, 100); // Slow down to visualize steps
    });

})();
</script>
</body>
</html>
